/**
 * CarAdvance — caradvance.sk / caradvance.cz: áfa- és jogi szövegek (Mr. JOB SK javaslata, 2026-10-23, B/F/G pontok)
 * A skcz-legal.mjs használja. Minden szöveg a célnyelven (sk / cs) van — a futásidejű fordító ezekhez nem nyúl.
 *
 *  FAQ   : [kérdés-regex, új kérdés | null, új válasz, oldal-szűrő (opcionális regex a relatív útvonalra)]
 *  RULES : [minta (string | regex), csere] — szövegben, attribútumokban (meta) és JSON-LD szövegekben
 *  JS    : [minta, csere] — a beágyazott scriptekben is (űrlapok, bérlési ablak, kártyák)
 */
const IT = '<\\/?(?:strong|em|b|span)(?:\\s[^<>]*)?>';                      // mondaton belüli kiemelés
const W = '(?:[^.<>"]|' + IT + ')*?';                        // mondaton belüli szakasz (pont, más tag, idézőjel nélkül)
const E = '(?:\\.|(?=")|(?=<(?!\\/?(?:strong|em|b|span)[\\s>])))';  // mondatvég vagy szöveg-vég
const r = (s, f = 'g') => new RegExp(s, f);

